ALTER TYPE "AuditAction" ADD VALUE 'MEMBER_UPDATED';
ALTER TYPE "AuditAction" ADD VALUE 'THEME_UPDATED';
ALTER TYPE "AuditAction" ADD VALUE 'SETTINGS_UPDATED';

