ALTER TABLE "Group" DROP COLUMN "createdById",
DROP COLUMN "isActive",
ADD COLUMN     "audience" TEXT,
ADD COLUMN     "leaderId" TEXT,
ADD COLUMN     "slug" TEXT NOT NULL;

